/**
 * @openelement/ui — the colour axis of the UTILITY rules (alpha15 S lane).
 *
 * CUSTOMIZATION.md's colour clause covers both authoring forms: "Colours still
 * come from this role table, never from a literal — either a role variable in
 * the sheet or a utility generated from a role (`bg-primary/14` compiles to
 * `color-mix` on `--color-primary`)."
 *
 * The authored-source guard cannot see a class attribute, so `bg-red-500`,
 * `bg-[rebeccapurple]` and `[color:var(--private-ink)]` all passed it: the
 * tokens are not declarations, and the rules they compile to are generated by
 * the engine. This guard decides the whole colour axis from the ENGINE's output
 * for the tokens the components actually carry.
 *
 * Two decisions keep it honest:
 *
 * 1. **The values are parsed by a mature CSS parser, never by splitting text.**
 *    `lightningcss` — the parser the installed toolchain itself uses — is
 *    resolved through `tailwindcss` (the declared devDep) and walked with its
 *    `Declaration` visitor. That yields a structured value per declaration
 *    (`color: rebeccapurple` arrives as `{type:'rgb',r:102,g:51,b:153}`), which
 *    is what makes a named colour, a hex, a colour function, a `var()` fallback
 *    and a `color-mix()` argument all decidable without a hand-written grammar.
 *    The utility SYNTAX itself is still the official engine's business.
 * 2. **The rule is "every colour dependency ends at a declared role", not "no
 *    literal appears".** So:
 *      - a `var()` in a colour value must name a declared role (an undeclared
 *        `--private-ink` fails, as does a palette step like `--color-red-500`);
 *      - a colour LITERAL is allowed only when it IS a declared role's resolved
 *        value. That is exactly the shape the engine emits for an alpha-modified
 *        role utility (`bg-primary/14` ships an inlined-value `color-mix`
 *        fallback and overrides it with `var(--color-primary)` under
 *        `@supports`), so the fallback is legal by VALUE IDENTITY rather than by
 *        a same-selector excuse that would let any literal through;
 *      - `transparent`, `currentColor` and the other non-colour keywords stay
 *        legal: they carry no author hue to escape the light/dark/forced-colors
 *        seats.
 *
 * The roles the generated rules consume are part of the public customization
 * surface, so the guard also proves each of them is named in CUSTOMIZATION.md's
 * inventory — a role cannot enter the contract through a utility alone.
 */
import { readFile, readdir } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { expect, test } from 'vitest';
import { compile } from 'tailwindcss';

const require = createRequire(import.meta.url);
/**
 * The parser the installed toolchain uses, reached through the engine the
 * package declares — the same resolution rule the build applies to its own
 * compiler. Typed loosely: the visitor shape is the only surface this guard
 * consumes.
 */
const lightningcss = (await import(
  createRequire(require.resolve('tailwindcss')).resolve('lightningcss')
)) as { transform(options: Record<string, unknown>): unknown };

const srcDir = fileURLToPath(new URL('../src', import.meta.url));
const themeSourcePath = join(srcDir, 'theme.css');
const repoRoot = fileURLToPath(new URL('../../..', import.meta.url));
const themeSource = await readFile(themeSourcePath, 'utf8');
const customizationDoc = await readFile(join(srcDir, '..', 'CUSTOMIZATION.md'), 'utf8');

/** The role names the component role source declares — the whole colour surface. */
function declaredRoles(css: string): Set<string> {
  const block = /@theme[^{]*\{([\s\S]*?)\n\}/.exec(css)?.[1] ?? '';
  return new Set([...block.matchAll(/(--color-[a-z0-9-]+)\s*:/g)].map((match) => match[1]!));
}

const ROLES = declaredRoles(themeSource);

/** The official engine's stylesheet loader (same shape as the delivery guard). */
async function loadStylesheet(id: string) {
  for (const candidate of [id, `${id}/index.css`]) {
    try {
      const path = require.resolve(candidate);
      if (path.endsWith('.css')) {
        return { path, base: dirname(path), content: await readFile(path, 'utf8') };
      }
    } catch {
      // Try the next spelling.
    }
  }
  throw new Error(`the colour-role guard cannot resolve the stylesheet "${id}"`);
}

/**
 * Compile the component-entry shape for one component: the theme layer, the
 * component's own role source, the utilities layer, and one admitted candidate
 * per literal class token the component's markup carries. Mirrors
 * `renderComponentUtilitiesEntry` (@openelement/router).
 */
async function compileComponentTokens(tokens: readonly string[]): Promise<string> {
  const entry =
    "@import 'tailwindcss/theme.css';\n" +
    `@import '${themeSourcePath}';\n` +
    "@import 'tailwindcss/utilities.css';\n" +
    tokens.map((token) => `@source inline("${token}");`).join('\n') +
    '\n';
  const compiler = await compile(entry, {
    base: repoRoot,
    from: join(repoRoot, '.openElement/utility-colour-roles-guard.css'),
    loadStylesheet,
  });
  return compiler.build([...tokens]);
}

/** Every literal class token a component's markup carries. */
function classTokens(tsx: string): string[] {
  const tokens = new Set<string>();
  for (const match of tsx.matchAll(/\bclass=(?:'([^']*)'|"([^"]*)")/g)) {
    for (const token of (match[1] ?? match[2] ?? '').split(/\s+/)) {
      if (token !== '') tokens.add(token);
    }
  }
  return [...tokens];
}

/** The class hooks a component's own sheet selects — not utility tokens. */
function hookNames(css: string): Set<string> {
  const names = new Set<string>();
  for (const match of css
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .matchAll(/\.(-?[A-Za-z_][A-Za-z0-9_-]*)/g)) {
    names.add(match[1]!);
  }
  return names;
}

/* ─── the value walk (lightningcss output → colour findings) ─────────────── */

interface ColourFinding {
  /** `var()` names referenced by a colour value. */
  vars: string[];
  /** Colour literals, keyed by a canonical string (`rgb:102,51,153,1`). */
  literals: string[];
  /** Bare identifiers seen in an unparsed colour value. */
  idents: string[];
  /** Percentages seen in an unparsed colour value, as their CSS text (`14%`). */
  percentages: string[];
}

/** Properties whose value carries colour, spelled as lightningcss reports them. */
const COLOUR_PROPERTY =
  /^(?:color|background|background-color|background-image|border|border-(?:top|right|bottom|left)(?:-color)?|border-color|outline|outline-color|fill|stroke|box-shadow|text-shadow|text-decoration|text-decoration-color|caret-color|accent-color|-webkit-text-fill-color)$/;

/** Identifiers that carry no author hue, or that are part of a value's grammar. */
const NEUTRAL_IDENTS = new Set([
  'transparent',
  'currentcolor',
  'inherit',
  'initial',
  'unset',
  'revert',
  'revert-layer',
  'none',
  'auto',
  // `color-mix()` / colour-space grammar.
  'in',
  'srgb',
  'srgb-linear',
  'display-p3',
  'a98-rgb',
  'prophoto-rgb',
  'rec2020',
  'xyz',
  'xyz-d50',
  'xyz-d65',
  'hsl',
  'hwb',
  'lab',
  'lch',
  'oklab',
  'oklch',
  'color',
  'mix',
  'shorter',
  'longer',
  'increasing',
  'decreasing',
  'hue',
  'from',
]);

/** A canonical key for one structured colour, or undefined for a non-colour. */
function colourKey(value: unknown): string | undefined {
  if (value === null || typeof value !== 'object') return undefined;
  const node = value as Record<string, unknown>;
  // `{ type: 'color', value: { type: 'oklch', … } }` — the wrapper lightningcss
  // uses inside an unparsed token list.
  if (node.type === 'color' && typeof node.value === 'object') return colourKey(node.value);
  const round = (input: unknown): string =>
    typeof input === 'number' ? input.toFixed(3).replace(/\.?0+$/, '') : String(input);
  const alpha = node.alpha === undefined ? '1' : round(node.alpha);
  // Fully transparent carries no author hue: `transparent` parses to this, and
  // the guard must not read the browser's `rgb(0 0 0 / 0)` as a colour.
  if (alpha === '0') return undefined;
  if (typeof node.r === 'number') {
    return `rgb:${round(node.r)},${round(node.g)},${round(node.b)},${alpha}`;
  }
  if (typeof node.l === 'number' && (node.c !== undefined || node.a !== undefined)) {
    return `${String(node.type)}:${round(node.l)},${round(node.c ?? node.a)},${round(
      node.h ?? 0,
    )},${alpha}`;
  }
  return undefined;
}

function walkValue(value: unknown, finding: ColourFinding): void {
  if (Array.isArray(value)) {
    for (const item of value) walkValue(item, finding);
    return;
  }
  if (value === null || typeof value !== 'object') return;
  const node = value as Record<string, unknown>;
  const key = colourKey(node);
  if (key !== undefined) {
    finding.literals.push(key);
    return;
  }
  if (node.type === 'var') {
    const inner = node.value as { name?: { ident?: string }; fallback?: unknown } | undefined;
    if (typeof inner?.name?.ident === 'string') finding.vars.push(inner.name.ident);
    walkValue(inner?.fallback, finding);
    return;
  }
  if (node.type === 'token') {
    const token = node.value as { type?: string; value?: unknown } | undefined;
    if (token?.type === 'ident' && typeof token.value === 'string') {
      finding.idents.push(token.value.toLowerCase());
    }
    if (token?.type === 'percentage' && typeof token.value === 'number') {
      const percent = (token.value * 100).toFixed(4).replace(/\.?0+$/, '');
      finding.percentages.push(`${percent}%`);
    }
    return;
  }
  if (node.type === 'function') {
    walkValue((node.value as { arguments?: unknown } | undefined)?.arguments, finding);
    return;
  }
  for (const inner of Object.values(node)) walkValue(inner, finding);
}

/** The minified sheet text: lightningcss' own normalization of the compile. */
function normalize(css: string): string {
  return String(
    (
      lightningcss.transform({
        filename: 'compiled.css',
        code: Buffer.from(css),
        minify: true,
      }) as { code: { toString(): string } }
    ).code,
  );
}

/**
 * The literal CSS text each role can resolve to, following `var()` aliases
 * (`--color-primary: var(--color-violet-700)`), read from the normalized sheet.
 * A role seated on several themes contributes several texts.
 */
function roleLiteralTexts(normalizedCss: string): Map<string, string[]> {
  // EVERY colour custom property is collected, not just the declared roles:
  // a role's value is usually an alias into the engine's default scale
  // (`--color-primary: var(--color-violet-700)`), and following that alias is
  // what turns the role into the literal text the fallback actually inlines.
  const declared = new Map<string, string[]>();
  for (const match of normalizedCss.matchAll(/(--color-[a-z0-9-]+)\s*:\s*([^;{}]+)/g)) {
    declared.set(match[1]!, [...(declared.get(match[1]!) ?? []), match[2]!.trim()]);
  }
  const resolve = (text: string, depth = 0): string[] => {
    if (depth > 8) return [];
    const alias = /^var\(\s*(--[a-z0-9-]+)\s*\)$/i.exec(text.trim());
    if (alias === null) return [text];
    return (declared.get(alias[1]!) ?? []).flatMap((inner) => resolve(inner, depth + 1));
  };
  const resolved = new Map<string, string[]>();
  for (const [name, texts] of declared) {
    if (!ROLES.has(name)) continue;
    resolved.set(name, [...new Set(texts.flatMap((text) => resolve(text)))]);
  }
  return resolved;
}

/**
 * What one role mixes to at one percentage over `transparent` — computed by
 * lightningcss, the same engine that computed the value being judged, so the
 * comparison is of engine results rather than of my arithmetic.
 */
function mixKey(literalText: string, percent: string): string | undefined {
  const declarations = declarationsOf(
    `x { color: color-mix(in srgb, ${literalText} ${percent}, transparent); }`,
  );
  const finding: ColourFinding = { vars: [], literals: [], idents: [], percentages: [] };
  for (const declaration of declarations) walkValue(declaration.value, finding);
  return finding.literals.length === 1 ? finding.literals[0] : undefined;
}

/** One declaration lightningcss reported, with its property name resolved. */
interface ParsedDeclaration {
  propertyName: string;
  value: unknown;
}

/**
 * Every declaration of a compiled sheet, read through lightningcss' visitor.
 * `custom` declarations carry a name; `unparsed` ones carry a structured
 * `propertyId`; everything else is already a known property.
 */
function declarationsOf(css: string): ParsedDeclaration[] {
  const declarations: ParsedDeclaration[] = [];
  lightningcss.transform({
    filename: 'compiled.css',
    code: Buffer.from(css),
    minify: false,
    visitor: {
      Declaration(declaration: {
        property: string;
        value: Record<string, unknown> & { name?: unknown; propertyId?: unknown; value?: unknown };
      }) {
        if (declaration.property === 'custom') {
          if (typeof declaration.value.name === 'string') {
            declarations.push({
              propertyName: declaration.value.name,
              value: declaration.value.value,
            });
          }
          return;
        }
        if (declaration.property === 'unparsed') {
          const propertyId = declaration.value.propertyId as { property?: unknown } | undefined;
          if (typeof propertyId?.property === 'string') {
            declarations.push({
              propertyName: propertyId.property,
              value: declaration.value.value,
            });
          }
          return;
        }
        declarations.push({ propertyName: declaration.property, value: declaration.value });
      },
    },
  });
  return declarations;
}

/** The role table's resolved colour values, following `var()` chains. */
function roleValues(declarations: readonly ParsedDeclaration[]): Map<string, Set<string>> {
  const raw = new Map<string, unknown[]>();
  const colours = new Map<string, Set<string>>();
  for (const declaration of declarations) {
    if (!ROLES.has(declaration.propertyName)) continue;
    raw.set(declaration.propertyName, [
      ...(raw.get(declaration.propertyName) ?? []),
      declaration.value,
    ]);
  }
  // Follow `var()` chains (`--color-primary: var(--color-violet-700)`), bounded
  // so a cycle cannot hang the guard. A role reached from several seats (light,
  // dark, forced-colors) accumulates every value it can resolve to.
  for (let pass = 0; pass < 8; pass++) {
    let grew = false;
    for (const [name, values] of raw) {
      const current = colours.get(name) ?? new Set<string>();
      for (const value of values) {
        const finding: ColourFinding = { vars: [], literals: [], idents: [], percentages: [] };
        walkValue(value, finding);
        for (const reference of finding.vars) {
          for (const literal of colours.get(reference) ?? []) {
            if (!current.has(literal)) {
              current.add(literal);
              grew = true;
            }
          }
        }
        for (const literal of finding.literals) {
          if (!current.has(literal)) {
            current.add(literal);
            grew = true;
          }
        }
      }
      colours.set(name, current);
    }
    if (!grew) break;
  }
  return colours;
}

/** The colour failures one compiled sheet carries. */
function colourFailures(css: string): { failures: string[]; consumedRoles: Set<string> } {
  const declarations = declarationsOf(css);
  const roles = roleValues(declarations);
  const allowedLiterals = new Set<string>();
  for (const values of roles.values()) for (const literal of values) allowedLiterals.add(literal);

  // The engine's own alpha fallback: for a role utility with an alpha modifier
  // it emits an INLINED-value `color-mix` beside the `var()` version. The
  // inlined value is not the role's colour — it is the role mixed with
  // transparent at the modifier's percentage — so it is admitted only by VALUE
  // IDENTITY: a literal is legal when some (role, percentage) pair the sheet
  // itself declares mixes to exactly that value, computed by the same parser.
  // A same-selector excuse would admit any literal written next to a role rule;
  // this cannot, because the mixed value has to match.
  const literalTexts = roleLiteralTexts(normalize(css));
  const pairs = new Map<string, Set<string>>();
  for (const declaration of declarations) {
    if (!COLOUR_PROPERTY.test(declaration.propertyName)) continue;
    const found: ColourFinding = { vars: [], literals: [], idents: [], percentages: [] };
    walkValue(declaration.value, found);
    const role = found.vars.length === 1 ? found.vars[0]! : undefined;
    if (role === undefined || !ROLES.has(role)) continue;
    for (const percent of found.percentages) {
      pairs.set(role, new Set([...(pairs.get(role) ?? []), percent]));
    }
  }
  for (const [role, percents] of pairs) {
    for (const text of literalTexts.get(role) ?? []) {
      for (const percent of percents) {
        const mixed = mixKey(text, percent);
        if (mixed !== undefined) allowedLiterals.add(mixed);
      }
    }
  }

  const failures: string[] = [];
  const consumedRoles = new Set<string>();
  for (const declaration of declarations) {
    if (!COLOUR_PROPERTY.test(declaration.propertyName)) continue;
    const finding: ColourFinding = { vars: [], literals: [], idents: [], percentages: [] };
    walkValue(declaration.value, finding);
    for (const reference of finding.vars) {
      if (ROLES.has(reference)) {
        consumedRoles.add(reference);
        continue;
      }
      failures.push(
        `${declaration.propertyName}: var(${reference}) — ${reference} is not a declared role`,
      );
    }
    for (const literal of finding.literals) {
      if (!allowedLiterals.has(literal)) {
        failures.push(`${declaration.propertyName}: ${literal} — a colour no role declares`);
      }
    }
    for (const ident of finding.idents) {
      if (!NEUTRAL_IDENTS.has(ident)) {
        failures.push(
          `${declaration.propertyName}: the identifier "${ident}" is not a neutral keyword — ` +
            'a named colour or an unsupported value form must become a role',
        );
      }
    }
  }
  return { failures, consumedRoles };
}

const componentFiles = (await readdir(srcDir))
  .filter((name) => name.startsWith('open-') && name.endsWith('.tsx'))
  .sort();

test('the guard has components to check', () => {
  expect(componentFiles.length).toBeGreaterThan(0);
  expect(ROLES.size).toBeGreaterThan(0);
});

const consumedByUtilities = new Set<string>();

for (const file of componentFiles) {
  test(`${file}: every generated colour resolves to a declared role`, async () => {
    const tag = file.replace(/\.tsx$/, '');
    const tsx = await readFile(join(srcDir, file), 'utf8');
    const hooks = hookNames(await readFile(join(srcDir, `${tag}.css`), 'utf8'));
    // The hooks are the component's own sheet's business (guarded separately);
    // this guard decides the tokens the ENGINE compiles.
    const tokens = classTokens(tsx).filter((token) => !hooks.has(token));
    expect(tokens.length, `${tag} must carry utility tokens`).toBeGreaterThan(0);
    const { failures, consumedRoles } = colourFailures(await compileComponentTokens(tokens));
    for (const role of consumedRoles) consumedByUtilities.add(role);
    expect(
      failures,
      `${tag}: a utility the component authors must generate its colour from the role table`,
    ).toEqual([]);
  });
}

test('the roles the generated utilities consume are part of the documented surface', () => {
  // A role entering the contract through a utility alone would be invisible to
  // an authored-CSS-only pin, so the generated side is checked here against the
  // inventory CUSTOMIZATION.md promises.
  expect(consumedByUtilities.size, 'the components must consume roles').toBeGreaterThan(0);
  const undocumented = [...consumedByUtilities].filter((role) => !customizationDoc.includes(role));
  expect(undocumented, 'every utility-consumed role must be documented').toEqual([]);
});

test('the guard fails every bypass shape, and passes the role forms', async () => {
  // The RED proof for this guard, on the guard's own compile path. Without it a
  // guard that silently matched nothing would look green.
  const bypasses = await compileComponentTokens([
    'bg-red-500',
    'bg-[rebeccapurple]',
    'bg-[#ef4444]',
    'text-[oklch(0.5_0.2_20)]',
    'bg-[red]',
    'border-[color:var(--private-ink)]',
    'bg-[color-mix(in_srgb,red_50%,transparent)]',
    'text-[color-mix(in_srgb,var(--color-primary)_50%,red)]',
  ]);
  const { failures } = colourFailures(bypasses);
  const joined = failures.join('\n');
  expect(joined, 'a palette step utility names an undeclared role').toContain(
    '--color-red-500 is not a declared role',
  );
  expect(joined, 'a named colour or a hex is not a role value').toContain(
    'a colour no role declares',
  );
  expect(joined, 'an undeclared custom property must fail').toContain(
    'var(--private-ink) — --private-ink is not a declared role',
  );
  // Every one of the eight shapes must be reported: a palette step, a named
  // colour, a hex, a colour function, a bare word, an undeclared variable, and
  // both mixes (whose parts are not role values).
  expect(failures.length, `every bypass shape must be reported:\n${joined}`).toBeGreaterThanOrEqual(
    7,
  );

  // …and the role forms, including the engine's alpha fallback, stay legal.
  const legal = await compileComponentTokens([
    'bg-primary',
    'bg-primary/14',
    'hover:bg-primary/23',
    'text-foreground',
    'text-muted-foreground',
    'text-destructive',
    'border-transparent',
    'focus-visible:outline-ring',
    'bg-[color-mix(in_srgb,var(--color-primary)_40%,transparent)]',
  ]);
  const legalResult = colourFailures(legal);
  expect(legalResult.failures, 'the role forms must stay legal').toEqual([]);
  expect(legalResult.consumedRoles.has('--color-primary')).toEqual(true);
});
